function s(e){if(!e)return"";const n=String(e);if(/^\d{4}-\d{2}-\d{2}$/.test(n))return n;const t=new Date(n);if(isNaN(t.getTime()))return n;const r=t.getFullYear(),a=String(t.getMonth()+1).padStart(2,"0"),i=String(t.getDate()).padStart(2,"0");return`${r}-${a}-${i}`}function o(e){if(!e)return"";const n=String(e);if(/^\d{4}-\d{2}-\d{2}$/.test(n))return n+" 00:00";const t=new Date(n);if(isNaN(t.getTime()))return n;const r=String(t.getHours()).padStart(2,"0"),a=String(t.getMinutes()).padStart(2,"0");return`${s(t)} ${r}:${a}`}const c=(e,n,t)=>s(t),d=(e,n,t)=>o(t);function g(){const e=new Date,n=e.getFullYear(),t=String(e.getMonth()+1).padStart(2,"0"),r=String(e.getDate()).padStart(2,"0");return`${n}-${t}-${r}`}export{c as a,d,s as f,g as t};
